import React, { useEffect, useState } from 'react';
import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
import { breakpoints } from 'app/theme/foundation';
import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';

export type ZimmWishlistAuthDrawerProps = {
  /**
   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
   * flows — those trigger a full browser redirect; the user lands back already logged in.
   */
  onAuthSuccess?: () => void;
  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
  intentId: string;
  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
   *  auth-gate handler — call the original action via onAuthSuccess instead. */
  children: React.ReactElement;
};

/**
 * Organism — wraps a single trigger element and gates its action behind auth.
 * If the customer is already registered the original onClick fires immediately.
 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
 *
 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
 */
export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
  const {
    isOpen,
    handleDrawerClose,
    handleTriggerClick,
    triggerRef,
    drawerTitle,
    description,
    emailValue,
    onEmailChange,
    onSendCode,
    onSignInWithApple,
    onSignInWithGoogle,
    isSocialEnabled,
    isPasswordlessEnabled,
    emailInputRef,
    onCreateAccount,
    isOtpAuthOpen,
    onOtpAuthClose,
    form,
    handlePasswordlessLogin,
    handleOtpVerification,
    registerModal,
  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });

  // SFCC-926 (Figma): wishlist auth drawer width is responsive — mobile full-width,
  // tablet (md–xl) 50% (large variant), desktop (≥ xl) 25% (small variant).
  // Both breakpoints from app/theme/foundation — same source as zimmDrawer.css.ts.
  // useEffect keeps window.matchMedia off the SSR render path (window not defined server-side).
  const [isTabletOrAbove, setIsTabletOrAbove] = useState(false);
  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
  useEffect(() => {
    const tabletMq = window.matchMedia(`(min-width: ${breakpoints.md})`);
    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
    setIsTabletOrAbove(tabletMq.matches);
    setIsDesktopOrAbove(desktopMq.matches);
    const onTablet = (e: MediaQueryListEvent) => setIsTabletOrAbove(e.matches);
    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
    tabletMq.addEventListener('change', onTablet);
    desktopMq.addEventListener('change', onDesktop);
    return () => {
      tabletMq.removeEventListener('change', onTablet);
      desktopMq.removeEventListener('change', onDesktop);
    };
  }, []);
  // CodeRabbit (PR review): `mobile` was incorrectly applying the PDP-specific 58px backdrop
  // strip (SFCC-736 AC 9) to a utility drawer. `large` below md collapses to full-height
  // via ZimmDrawer's baseStyle without the strip.
  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';

  return (
    <>
      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
      <ZimmDrawer
        isOpen={isOpen}
        onClose={handleDrawerClose}
        size={drawerSize}
        title={drawerTitle}
        finalFocusRef={triggerRef}
        initialFocusRef={emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={description}
            emailValue={emailValue}
            onEmailChange={onEmailChange}
            onSendCode={onSendCode}
            onSignInWithApple={onSignInWithApple}
            onSignInWithGoogle={onSignInWithGoogle}
            onCreateAccount={onCreateAccount}
            socialEnabled={isSocialEnabled}
            passwordlessEnabled={isPasswordlessEnabled}
            initialFocusRef={emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...registerModal} />
      <OtpAuth
        isOpen={isOtpAuthOpen}
        onClose={onOtpAuthClose}
        form={form}
        handleSendEmailOtp={handlePasswordlessLogin}
        handleOtpVerification={handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

const path = require('path');
const webpack = require('webpack');

/** @type { import('@storybook/react-webpack5').StorybookConfig } */
const config = {
  stories: ['../overrides/**/*.stories.@(js|jsx|ts|tsx|mdx)'],
  // Serve overrides/app/static/ so self-hosted assets resolve in Storybook the same way
  // getAssetUrl resolves them in the app. Mapped to /static (rather than the bare directory)
  // so the fallback path in overrides/app/theme/fontFace.tsx is a real URL here instead of a
  // silent 404 — without this, Storybook renders the fallback font while the app renders
  // Futura Round, and no visual comparison made in Storybook can be trusted.
  staticDirs: [{ from: '../overrides/app/static', to: '/static' }],
  addons: [
    '@storybook/addon-webpack5-compiler-babel',
    '@storybook/addon-links',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
  ],
  framework: {
    name: '@storybook/react-webpack5',
    options: {},
  },
  webpackFinal: async (webpackConfig) => {
    // Resolve PWA Kit package aliases so imports from
    // '@salesforce/retail-react-app/...' resolve correctly.
    webpackConfig.resolve.alias = {
      ...webpackConfig.resolve.alias,
      // Project path aliases — keep in sync with babel.config.js, tsconfig.json
      // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
      '~': path.resolve(__dirname, '..'),
      app: path.resolve(__dirname, '../overrides/app'),
      '@salesforce/retail-react-app': path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      '@salesforce/pwa-kit-react-sdk': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-react-sdk'),
      '@salesforce/pwa-kit-runtime': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-runtime'),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, '../node_modules/@salesforce/commerce-sdk-react'),
      // @tanstack/react-query publishes separate CJS (build/lib/index.js) and ESM
      // (build/lib/index.mjs) entry points via its `exports` map. commerce-sdk-react's
      // dist `require()`s the CJS file while a raw `import` (used by a Storybook story
      // authored under overrides/) resolves the ESM file — two distinct files, so two
      // distinct copies of QueryClientProvider's module-scope Context objects. A
      // QueryClientProvider rendered from one copy is invisible to useQueryClient() called
      // from the other, throwing "No QueryClient set" despite a provider clearly being an
      // ancestor — confirmed via rightBar/index.stories.tsx's Wishlist icon
      // (withRegistration -> useCurrentCustomer). Force both `import` and `require` to the
      // same physical file so there is only ever one copy.
      '@tanstack/react-query': path.resolve(__dirname, '../node_modules/@tanstack/react-query/build/lib/index.js'),
    };

    // Allow Storybook to process JSX inside @salesforce/retail-react-app,
    // which ships un-compiled .jsx source files.

  },
},
resolve: {
  // Keep in sync with babel.config.js, tsconfig.json, .storybook/main.js
  // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
  alias: {
    '~': path.resolve(__dirname),
    app: path.resolve(__dirname, 'overrides/app'),
    // @salesforce/commerce-sdk-react@5.2.0's published package.json declares
    // main: "dist/index.js", but the published tarball has no dist/ at all —
    // the real entry file is index.js at the package root (confirmed by
    // unpacking the npm tarball directly; same defect persists through at
    // least 5.4.0). Node/webpack resolve this fine because their module
    // resolution falls back to a package's root index.js when `main` doesn't
    // exist; Vite/Vitest's resolver has no such fallback and fails with
    // "Failed to resolve entry for package". The same broken-`main` defect
    // also breaks Vite/Vitest's resolution of this package's subpath exports
    // (`/components`, `/page-designer`) even though each has a real
    // index.js on disk and Node/webpack resolve them fine — an earlier
    // revision of this comment claimed subpaths "resolve normally,
    // untouched by this alias"; that was wrong, disproven when
    // overrides/app/components/_app/index.tsx (SFCC-863) became the first
    // file in overrides/ to import either subpath and its test failed to
    // resolve them. Add a new exact-match entry here for each subpath as
    // one gets a real consumer, rather than trying to express this as a
    // single prefix/RegExp alias.
    // Order matters: Vite's alias matching treats a bare-specifier key as a prefix match
    // too (`importee === key || importee.startsWith(key + '/')`), so the subpath entries
    // must come before the bare '@salesforce/commerce-sdk-react' entry below or that
    // broader entry wins first and mis-resolves the subpath.
    '@salesforce/commerce-sdk-react/components': path.resolve(
      __dirname,
      'node_modules/@salesforce/commerce-sdk-react/components/index.js',
    ),
    '@salesforce/commerce-sdk-react/page-designer': path.resolve(
      __dirname,
      'node_modules/@salesforce/commerce-sdk-react/page-designer/index.js',
    ),
    '@salesforce/commerce-sdk-react': path.resolve(__dirname, 'node_modules/@salesforce/commerce-sdk-react/index.js'),
  },

